string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".txt");
try{await File.WriteAllTextAsync(file,"Chào");Console.WriteLine(await Read(file,CancellationToken.None));using var cts=new CancellationTokenSource();cts.Cancel();try{await Read(file,cts.Token);}catch(OperationCanceledException){Console.WriteLine("canceled");}
try{await RunFailing();}catch(InvalidOperationException){Console.WriteLine("observed");}
Console.Write("before,");await Task.CompletedTask;Console.WriteLine("after");}
finally{File.Delete(file);}
static async Task<string> Read(string file,CancellationToken token)=>await File.ReadAllTextAsync(file,token);
static async Task RunFailing(){using var r=new Resource();await Task.FromException(new InvalidOperationException());}
class Resource:IDisposable{public void Dispose()=>Console.WriteLine("disposed");}

